package main

import (
	"database/sql"
	"encoding/json"
	"net/http"
	"os"

	_ "github.com/mattn/go-sqlite3"
)

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "3000"
	}

	db, _ := sql.Open("sqlite3", ":memory:")
	db.Exec("CREATE TABLE IF NOT EXISTS items (id INTEGER PRIMARY KEY, name TEXT, quantity INTEGER)")

	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]string{"status": "ok", "db": "connected"})
	})

	http.HandleFunc("/items", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		switch r.Method {
		case "POST":
			var body struct {
				Name     string `json:"name"`
				Quantity int    `json:"quantity"`
			}
			json.NewDecoder(r.Body).Decode(&body)
			result, _ := db.Exec("INSERT INTO items (name, quantity) VALUES (?, ?)", body.Name, body.Quantity)
			id, _ := result.LastInsertId()
			w.WriteHeader(http.StatusCreated)
			json.NewEncoder(w).Encode(map[string]interface{}{"id": id, "name": body.Name, "quantity": body.Quantity})
		case "GET":
			rows, _ := db.Query("SELECT id, name, quantity FROM items")
			var items []map[string]interface{}
			for rows.Next() {
				var id int
				var name string
				var quantity int
				rows.Scan(&id, &name, &quantity)
				items = append(items, map[string]interface{}{"id": id, "name": name, "quantity": quantity})
			}
			json.NewEncoder(w).Encode(items)
		}
	})

	http.ListenAndServe(":"+port, nil)
}
